select 'SAT_AGREEMENT_COMMERCIAL_TERMS' satellite,'HUB_AGREEMENT' parent_table,count_if(s.AGREEMENT_HKEY is null or p.k is null) orphan_or_null_rows from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AGREEMENT_COMMERCIAL_TERMS s left join (select distinct AGREEMENT_HKEY k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_AGREEMENT) p on p.k=s.AGREEMENT_HKEY where startswith(s.RECORD_SOURCE, 'OPUS_') and (s.AGREEMENT_HKEY is null or s.AGREEMENT_HKEY <> TO_BINARY(REPEAT('0', 32), 'HEX'))
union all select 'SAT_AGREEMENT_DEFINITION' satellite,'HUB_AGREEMENT' parent_table,count_if(s.AGREEMENT_HKEY is null or p.k is null) orphan_or_null_rows from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AGREEMENT_DEFINITION s left join (select distinct AGREEMENT_HKEY k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_AGREEMENT) p on p.k=s.AGREEMENT_HKEY where startswith(s.RECORD_SOURCE, 'OPUS_') and (s.AGREEMENT_HKEY is null or s.AGREEMENT_HKEY <> TO_BINARY(REPEAT('0', 32), 'HEX'))
union all select 'SAT_COMMON_ADDRESS' satellite,'HUB_LOCATION' parent_table,count_if(s.LOCATION_HKEY is null or p.k is null) orphan_or_null_rows from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS s left join (select distinct LOCATION_HKEY k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_LOCATION) p on p.k=s.LOCATION_HKEY where startswith(s.RECORD_SOURCE, 'OPUS_') and (s.LOCATION_HKEY is null or s.LOCATION_HKEY <> TO_BINARY(REPEAT('0', 32), 'HEX'))
union all select 'SAT_COMMON_ADMIN_GEOGRAPHY' satellite,'HUB_LOCATION' parent_table,count_if(s.LOCATION_HKEY is null or p.k is null) orphan_or_null_rows from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADMIN_GEOGRAPHY s left join (select distinct LOCATION_HKEY k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_LOCATION) p on p.k=s.LOCATION_HKEY where startswith(s.RECORD_SOURCE, 'OPUS_') and (s.LOCATION_HKEY is null or s.LOCATION_HKEY <> TO_BINARY(REPEAT('0', 32), 'HEX'))
union all select 'SAT_COMMON_CLASSIFICATION' satellite,'HUB_PARTY' parent_table,count_if(s.PARTY_HKEY is null or p.k is null) orphan_or_null_rows from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_CLASSIFICATION s left join (select distinct PARTY_HKEY k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_PARTY) p on p.k=s.PARTY_HKEY where startswith(s.RECORD_SOURCE, 'OPUS_') and (s.PARTY_HKEY is null or s.PARTY_HKEY <> TO_BINARY(REPEAT('0', 32), 'HEX'))
;
